(()=>{try{document.querySelectorAll('.cursor, .trail, .cursor-dot, .cursor-ring').forEach(el=>el.remove());const isTouch=('ontouchstart'in window)||navigator.maxTouchPoints>0;const smallScreen=window.innerWidth<=768;if(isTouch||smallScreen)return;document.body.classList.add('custom-cursor-enabled');const cursor=document.createElement('div');cursor.className='cursor';const ring=document.createElement('div');ring.className='cursor-ring';const dot=document.createElement('div');dot.className='cursor-dot';cursor.appendChild(ring);cursor.appendChild(dot);const trail=document.createElement('div');trail.className='trail';document.body.appendChild(cursor);document.body.appendChild(trail);function updateAccent(){const styles=getComputedStyle(document.body);const accent=styles.getPropertyValue('--badge').trim()||styles.getPropertyValue('--title').trim()||'#8b5cf6';dot.style.background=accent;ring.style.borderTopColor=accent;trail.style.background=accent+'33';}
updateAccent();const observer=new MutationObserver(updateAccent);observer.observe(document.body,{attributes:true,attributeFilter:['class','style']});let mouseX=window.innerWidth/2;let mouseY=window.innerHeight/2;let currentX=mouseX;let currentY=mouseY;let trailX=mouseX;let trailY=mouseY;window.addEventListener('mousemove',event=>{mouseX=event.clientX;mouseY=event.clientY;const overVerticalScrollbar=mouseX>=document.documentElement.clientWidth;const overHorizontalScrollbar=mouseY>=document.documentElement.clientHeight;if(overVerticalScrollbar||overHorizontalScrollbar){cursor.style.opacity='0';trail.style.opacity='0';}else{if(cursor.style.opacity==='0'){cursor.style.opacity='1';trail.style.opacity='1';}}});function animate(){currentX+=(mouseX-currentX)*0.18;currentY+=(mouseY-currentY)*0.18;trailX+=(mouseX-trailX)*0.08;trailY+=(mouseY-trailY)*0.08;cursor.style.left=currentX+'px';cursor.style.top=currentY+'px';trail.style.left=trailX+'px';trail.style.top=trailY+'px';requestAnimationFrame(animate);}
requestAnimationFrame(animate);const hoverSelector='a, button, .card, .project-card, .nav-link, .cert-nav__link, [role="button"], [onclick], .btn, summary, label';const textSelector='input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="file"]), textarea, select, [contenteditable="true"], [contenteditable="plaintext-only"]';function updateCursorState(target){const textTarget=target&&target.closest(textSelector);const hoverTarget=target&&target.closest(hoverSelector);cursor.classList.toggle('text',Boolean(textTarget));cursor.classList.toggle('hover',!textTarget&&Boolean(hoverTarget));}
document.addEventListener('pointerover',event=>updateCursorState(event.target));document.addEventListener('focusin',event=>updateCursorState(event.target));document.addEventListener('focusout',()=>{requestAnimationFrame(()=>updateCursorState(document.activeElement));});document.addEventListener('mousedown',event=>{updateCursorState(event.target);cursor.classList.add('click');});document.addEventListener('mouseup',()=>cursor.classList.remove('click'));document.addEventListener('pointercancel',()=>cursor.classList.remove('click'));document.addEventListener('mouseleave',()=>{cursor.style.opacity='0';trail.style.opacity='0';});document.addEventListener('mouseenter',()=>{cursor.style.opacity='1';trail.style.opacity='1';});}catch(error){console.error('Custom cursor init failed',error);}})();;